def _inline_r_setup(code: str) -> str:
    flags = re.MULTILINE | re.DOTALL
    code_ = None
    try:
        code_ = re.sub(r'^ *# *REM [^\n]*$\n?', '', code, flags=flags)
        code_ = re.sub(r'^ *# STARTBLOCK *$\n', '', code_, flags=flags)
        code_ = re.sub(r'^ *# ENDBLOCK *$\n?', '', code_, flags=flags)
        code_ = code_.rstrip()
    finally:
        if code_:
            return code_
        else:
            return code

def _inline_r_setup(code: str) -> str:
    """
    Some behaviour of R cannot be configured via env variables, but can
    only be configured via R options once R has started. These are set here.
    """
    lines = code.splitlines()
    for i in range(len(lines)):
        if lines[i].startswith("options("):
            lines[i] = 'options(' + lines[i][8:-1] + ')'
        elif lines[i].startswith("option("):
            lines[i] = 'option(' + lines[i][8:-1] + ')'
        elif lines[i].startswith("(.inObject("):
            lines[i] = '.inObject(' + lines[i][10:-1] + ')'
        elif lines[i].startswith("(.Machine("):
            lines[i] = '.Machine(' + lines[i][9:-1] + ')'
        elif lines[i].startswith("(.RNGkind("):
            lines[i] = '.RNGkind(' + lines[i][10:-1] + ')'
    code = "\n".join(lines)
    return code

