def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    s = s.strip()
    parts = s.split(".")
    if len(parts) < 3:
        raise ValueError(f"Version string {s} has fewer than 3 parts")
    try:
        major, minor, micro = [int(p) for p in parts[:3]]
    except ValueError:
        raise ValueError(f"Invalid version string {s}")
    return major, minor, micro

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    # Step 1: Parse the version string into its individual components
    # based on the period ('.') and underscore ('_') characters.
    components = re.split(r'[._]', s)

    # Step 2: Convert each component into an integer. If a component
    # cannot be converted to an integer, set that component to 0.
    int_components = []
    for component in components:
        try:
            int_components.append(int(component))
        except ValueError:
            int_components.append(0)

    # Step 3: Return the tuple of integer components.
    return tuple(int_components)

