def extostr(cls, e, max_level=30, max_path_level=5):
    """Format an exception.

    Args:
        e (Exception): Any exception instance.
        max_level (int, optional): Maximum call stack level. Defaults to 30.
        max_path_level (int, optional): Maximum path level. Defaults to 5.

    Returns:
        str: The exception readable string.
    """
    try:
        tb = sys.exc_info()[2]
        tbinfo = traceback.extract_tb(tb, max_level)
        path, line, name, src = '', '', '', ''
        for tb_tmp in tbinfo:
            if max_path_level and tb_tmp.py_file != '':
                path += tb_tmp.py_file + '::' * max_path_level
            line += str(tb_tmp.line) + '::'
            name += tb_tmp.name
            src += tb_tmp.src
        ret = { 'msg': str(e), 'file': path, 'line': line, 'name': name, 'src': src }
        if isinstance(e, s_exc.SynErr):
            ret['syn:err'] = e.errinfo
        return (e.__class__.__name__, ret)
    except Exception as e2:
        return repr(e2)
