def minimalBases(classes: List[type]) -> List[type]:
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not classes:
        return []
    bases = [{c} for c in classes]
    for a, b in itertools.combinations(bases, 2):
        if a & b:
            a |= b
            bases.remove(b)
    return [b for b in bases]
