def check_digests_present_and_used(manifest_files, digests_used):
    # Get all digests required in the manifest files
    required_digests = set()
    for manifest_file in manifest_files:
        with open(manifest_file) as f:
            manifest = f.read()
            for line in manifest.splitlines():
                if line.startswith("Name:"):
                    name = line.split()[1]
                elif line.startswith("Digest:"):
                    required_digests.add(name + ":" + line.split()[1])

    # Check if all required digests are present in the digests_used set
    if required_digests - digests_used:
        raise ValueError(f"Missing digests: {required_digests - digests_used}")

    # Check if all digests used are present in the required digests
    if digests_used - required_digests:
        raise ValueError(f"Extra digests: {digests_used - required_digests}")

def parse_ld_json(json_data: str):
    """Parse the output of the Linux command 'ldd --json' and return a dict."""
    import json
    parsed_data = json.loads(json_data)
    ld_data = {}
    for d in parsed_data:
        for lib in d["lib"]:
            ld_data[lib["name"]] = lib["path"]
    return ld_data

def ldd(path: str):
    """Equivalent of the Linux command 'ldd', but with the API of load_shared_library."""
    import subprocess
    p = subprocess.Popen(['ldd', path],
                         stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    output, error = p.communicate()
    if error:
        raise ValueError(f"Error executing command with path {path}: {error}")
    data = parse_ld_json(output.decode("utf-8"))
    return data

