    if self.inhibitors != prior.inhibitors:
        raise ValueError("InventoryValidator objects must have the same inhibitors")

    # Check that the current inventory is a superset of the prior inventory
    for parameter in self.parameters:
        if parameter not in prior.parameters:
            raise ValueError("Parameter {0} not found in prior inventory".format(parameter))

    for species in self.species:
        if species not in prior.species:
