def extract_number_and_supplement_from_issue_element(issue):
    """
    Extract the number and supplement from the <issue>xxxx</issue> element.
    """
    import re

    pattern = r"(\d+)\s?([Ss]uppl?\s?\.?\s?\d*)?"
    match = re.search(pattern, issue)
    if match:
        number = match.group(1)
        supplement = match.group(2)
        if supplement:
            return (number, supplement)
        else:
            return (number, None)
    else:
        raise Exception("Unable to extract number and supplement from issue element: {}".format(issue))

