def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    return [apply_absorption(arg) and apply_negative_absorption(arg) for arg in args]

def apply_absorption(arg):
    if isinstance(arg, (tuple, list)):
        if len(arg) == 2:
            return arg[0] if arg[0] == arg[1] else arg
        else:
            return arg
    else:
        raise ValueError(f"Unable to apply absorption to {arg}")

def apply_negative_absorption(arg):
    if isinstance(arg, (tuple, list)):
        if len(arg) == 3:
            return arg[0] if arg[0] == arg[1] else arg
        else:
            return arg
    else:
        raise ValueError(f"Unable to apply negative absorption to {arg}")
