def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Args:
        validate_objects (bool, optional): Validate objects in the hierarchy. Defaults to True.
        check_digests (bool, optional): Check object digests. Defaults to True.
        show_warnings (bool, optional): Show warnings. Defaults to False.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    # Check that self.root is not None
    if self.root is None:
        raise ValueError("Root must be set before calling validate_hierarchy().")

    # Validate the root object
    if validate_objects:
        if not self.validate_object(self.root):
            if show_warnings:
                warnings.warn("Root object is invalid.")

    # Recursively validate the hierarchy
    for node in self.preorder_nodes(self.root):
        num_objects += 1

        # Check that the node's digest is valid
        if check_digests and not self.is_valid_digest(node.digest):
            if show_warnings:
                warnings.warn("Invalid digest for object with ID '{0}'.".format(node.id))

        # Validate the node's object
        if validate_objects and not self.validate_object({"id": node.id}):
            if show_warnings:
                warnings.warn("Object with ID '{0}' is invalid.".format(node.id))
        else:
            good_objects += 1

    return num_objects, good_objects

