def parse_subparser_arguments(unparsed_arguments):
    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    """
    # Create a new argument parser instance for each subparser
    parser_dict = {subcommand: argparse.ArgumentParser(prog=subcommand) for subcommand in subparsers.keys()}

    # Add all common arguments to each subparser
    for common_arg in self._common_args:
        for parser in parser_dict.values():
            parser.add_argument(common_arg)

    # Add all arguments from the arguments to the argument parser
    for args, kwargs in self._arguments:
        for parser in parser_dict.values():
            parser.add_argument(*args, **kwargs)

    # Parse the arguments with each subparser
    parsed_args = {}
    remaining_args = []
    for subcommand, parser in parser_dict.items():
        namespace, new_args = parser.parse_known_args(unparsed_arguments)
        parsed_args[subcommand] = namespace
        unparsed_arguments = new_args

    return parsed_args, unparsed_arguments
