def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    base = len(alphabet)
    result = []
    while number > 0:
        result.append(alphabet[number % base])
        number //= base

    if padding is not None and len(result) < padding:
        result.extend([alphabet[0]] * (padding - len(result)))

    return "".join(reversed(result))

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if padding is not None and len(alphabet) < padding:
        raise ValueError("Length of alphabet must be greater than or equal to the padding")

    if number == 0:
        return "0"

    result = ""
    while number > 0:
        result = alphabet[number % len(alphabet)] + result
        number //= len(alphabet)

    if padding is not None:
        result = (padding - len(result)) * "0" + result

    return result

