def prepare_repository_from_archive(archive_path, filename=None, tmp_path="/tmp"):
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    if not os.path.exists(archive_path):
        raise ValueError("No such file or directory: '{}'".format(archive_path))

    if not filename:
        filename = os.path.basename(archive_path)

    if not os.path.isdir(tmp_path):
        raise ValueError("The path '{}' does not exist or is not a directory".format(tmp_path))

    tmp_dir = tempfile.mkdtemp(dir=tmp_path)
    archive_name = filename

    # Execute the appropriate uncompress function based on the file extension
    if archive_path.endswith(".tar.gz"):
        uncompress_func = tarfile.open
        uncompress_args = {"mode": "r:gz"}
    elif archive_path.endswith(".tar.bz2"):
        uncompress_func = tarfile.open
        uncompress_args = {"mode": "r:bz2"}
    elif archive_path.endswith(".zip"):
        uncompress_func = zipfile.ZipFile
        uncompress_args = {}
    else:
        raise ValueError("Unsupported archive format: '{}'".format(archive_path))

    try:
        # Extract the archive to the temporary directory
        with uncompress_func(archive_path, "r") as f:
            f.extractall(tmp_dir)
    except IOError as e:
        six.raise_from(ValueError(str(e)), None)

    # Return the file repo url
    return "file://{}/{}".format(tmp_path, archive_name)
