def parse_frequency(frequency):
    """
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    """
    if not frequency:
        return None
    if frequency.lower() == "always":
        return None

    parts = frequency.lower().split(" ")
    if len(parts) != 2:
        raise ValueError("Invalid frequency string: {}".format(frequency))
    number = parts[0]
    unit = parts[1]

    # Convert number to integer
    try:
        number = int(number)
    except ValueError:
        raise ValueError("Invalid frequency string: {}".format(frequency))

    # Convert unit to timedelta
    if unit == "day":
        return datetime.timedelta(days=number)
    elif unit == "week":
        return datetime.timedelta(weeks=number)
    elif unit == "month":
        return datetime.timedelta(weeks=number * 4)
    elif unit == "year":
        return datetime.timedelta(weeks=number * 52)
    else:
        raise ValueError("Invalid frequency string: {}".format(frequency))

