    parsed_conf = {}
    logging_records = []
    for conf_file in conf_files:
        try:
            with open(conf_file) as f:
                conf = json.load(f)
        except json.JSONDecodeError as e:
            logging_records.append(logging.LogRecord("decoding", conf_file, e))
        else:
            parsed_conf[conf_file] = conf

    if overrides is not None:
        for k, v in overrides.items():
            try:
                parsed_conf[k] = v
            except KeyError:
                logging_records.append(logging.LogRecord("override key not found", k, v))

    if resolve_env is not None:
