        if not issubclass(candidate_class, iface_class):
            return False
        for attr_name in dir(iface_class):
            attr = getattr(iface_class, attr_name)
            if isinstance(attr, abc.abstractmethod):
                # This is an abstract method, check if it is implemented
                # in the candidate
                candidate_attr = getattr(candidate_class, attr_name)
                if candidate_attr is None or not callable(candidate_attr):
                    return False
        return True
