def _convert_non_cli_args(parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    parser = get_parser(parser_name)
    for opt in parser.options:
        if opt.name in values_dict and opt.is_constant:
            values_dict[opt.name] = opt.value
        elif opt.name in values_dict and type(values_dict[opt.name]) != opt.type:
            values_dict[opt.name] = opt.type(values_dict[opt.name])
        elif opt.name not in values_dict and opt.default is not None:
            values_dict[opt.name] = opt.default
    return values_dict

