def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    # Validate input
    if not isinstance(plugin_dir, str):
        raise ValueError("Invalid input: plugin_dir should be a string")

    # Parse the plugin spec
    try:
        plugin_spec = json.load(open(os.path.join(plugin_dir, "plugin.json")))
    except (FileNotFoundError, json.JSONDecodeError) as e:
        raise ValueError(f"Failed to parse plugin spec: {e}")

    # Flatten the plugin spec
    flat_dict = {}
    for key, value in plugin_spec.items():
        if isinstance(value, dict):
            for nested_key, nested_value in value.items():
                flat_dict[f"{key}.{nested_key}"] = nested_value
        else:
            flat_dict[key] = value

    # Check if the dictionary is empty
    if not flat_dict:
        raise ValueError("The plugin spec is empty")

    return flat_dict

